import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const a = input[1].split(" ").map(Number).sort((x, y) => x - y);
const b = input[2].split(" ").map(Number).sort((x, y) => x - y);

// 両方を昇順にして、小さいほうを進める
let i = 0;
let j = 0;
let best = Infinity;
while (i < a.length && j < b.length) {
  best = Math.min(best, Math.abs(a[i] - b[j]));
  if (a[i] < b[j]) i++;
  else j++;
}
console.log(best);
